def search_users(query: str) -> list[dict]:
    all_users = store.find_all()
    query = query.lower()
    matches = []
    for user in all_users:
        if query in user["name"].lower() or query in user["email"].lower():
            matches.append(user)
    return sorted(matches, key=lambda u: u["id"])

